# German texts for the clan intrigue (Haus Marrovel, the Ruskwebers, the strangers from the map's edge)
# and the Ledger. Source: data/dialogue/clans.json.
KEEP = ["Wren", "Pip", "Marlo", "Vash", "Fenrick", "Ottilie", "Brannoc", "Mother Grell", "Sable", "Morrow", "Aldra", "Amir", "Elma", "Farida", "Heider", "Kenan", "Leith", "Lejla", "Lipka", "Mirza", "Nail"]
T = {
"Wren: Welcome to the Crooked Kettle. Rooms by the night, secrets by the hour.": "Wren: Willkommen im Schiefen Kessel. Zimmer pro Nacht, Geheimnisse pro Stunde.",
"Wren: Two clans eat in my dining room. Haus Marrovel by the window, the Ruskwebers by the door.": "Wren: In meinem Speisesaal essen zwei Clans. Haus Marrovel am Fenster, die Ruskweber an der Tür.",
"Wren: Marrovel keeps the old Rift pacts. The Ruskwebers keep everyone who works the mines.": "Wren: Marrovel hütet die alten Rissurkunden. Die Ruskweber halten jeden, der in den Minen schuftet.",
"Wren: My advice? Trust nobody who pays on time. That's a joke. Mostly.": "Wren: Mein Rat? Trau keinem, der pünktlich zahlt. Das ist ein Witz. Meistens.",
"Wren: Ilo Vash sold your blank battle record to the Ruskwebers.": "Wren: Ilo Vash hat dein leeres Kampfprotokoll an die Ruskweber verkauft.",
"Wren: Then he sold them a second copy. He calls it customer care.": "Wren: Dann hat er ihnen eine zweite Abschrift verkauft. Er nennt das Kundenpflege.",
"Wren: A Ruskweber came asking for you by name. With a letter in Fenrick's hand.": "Wren: Ein Ruskweber hat nach dir gefragt. Mit Namen. Und mit einem Brief in Fenricks Schrift.",
"Wren: I told him you'd died. He tipped me. Lovely man.": "Wren: Ich hab gesagt, du bist tot. Er hat Trinkgeld gegeben. Reizender Mann.",
"Wren: Corvane, is it? Write to me. And never sign your letters.": "Wren: Corvane, ja? Schreib mir. Und unterschreib nie deine Briefe.",
"Pip: You're the map kid. Good. Maps don't gossip.": "Pip: Du bist das Kartenkind. Gut. Karten tratschen nicht.",
"Pip: Last night I fought a Ruskweber Spirling at the Rift edge. Clan duels are banned.": "Pip: Letzte Nacht hab ich am Rissrand gegen einen Ruskweber-Spirling gekämpft. Clanduelle sind verboten.",
"Pip: It lost. Then it went silent, like the Hush took it, and walked into the Rift.": "Pip: Er hat verloren. Dann ist er verstummt, als hätte ihn die Stille geholt, und in den Riss gegangen.",
"Pip: Its breeder ran in after it. Neither came out. Help me keep this quiet?": "Pip: Sein Züchter ist hinterher. Keiner kam zurück. Hilfst du mir, das still zu halten?",
"I'll cover it up": "Ich vertusche es",
"Tell the Wardens": "Den Hütern sagen",
"Pip: Someone slipped a note under my door that night. 'Duel at the Rift edge. Win.' No name.": "Pip: Jemand hat mir in der Nacht einen Zettel unter die Tür geschoben. 'Duell am Rissrand. Gewinn.' Kein Name.",
"Pip: Grandfather smiles at me more lately. I don't like it.": "Pip: Großvater lächelt mich in letzter Zeit öfter an. Das gefällt mir nicht.",
"Ash in the brooding oven": "Asche im Brutofen",
"You burned the silent Spirling's things in a cold breeding oven, to hide Pip's duel.": "Du hast die Sachen des verstummten Spirlings in einem kalten Brutofen verbrannt, um Pips Duell zu verbergen.",
"The oven belongs to Ilo Vash's brother-in-law. Somebody swept up the ash and weighed it.": "Der Ofen gehört dem Schwager von Ilo Vash. Jemand hat die Asche zusammengekehrt und gewogen.",
"Marlo: Marlo, Spirling doctor. I mend legs, wings and the odd broken heart.": "Marlo: Marlo, Spirling-Arzt. Ich flicke Beine, Flügel und hin und wieder ein gebrochenes Herz.",
"Marlo: What can I do for you?": "Marlo: Was kann ich für dich tun?",
"A check-up": "Eine Untersuchung",
"Be my alibi?": "Mein Alibi sein?",
"Nothing": "Nichts",
"Marlo: Again? Fine. You were here all night, holding a Puddlet's flipper.": "Marlo: Schon wieder? Gut. Du warst die ganze Nacht hier und hast eine Puddlet-Flosse gehalten.",
"Marlo: Every lie I tell for you costs something. I just don't know what yet.": "Marlo: Jede Lüge für dich kostet etwas. Ich weiß nur noch nicht, was.",
"Vash: Warden Ilo Vash, Clan Duels Office. Complaints are taken at noon.": "Vash: Hüter Ilo Vash, Amt für Clanduelle. Beschwerden nehme ich um zwölf an.",
"Vash: The office closes at noon.": "Vash: Das Amt schließt um zwölf.",
"Vash: A blank battle record for Pip Kael's little evening? 300 coins.": "Vash: Ein leeres Kampfprotokoll für Pip Kaels kleinen Abend? 300 Münzen.",
"Vash: Paperwork is a craft. Crafts cost money.": "Vash: Papierkram ist ein Handwerk. Handwerk kostet.",
"Pay 300 coins": "300 Münzen zahlen",
"Not today": "Heute nicht",
"Vash: You reported a clan duel. To me. How refreshing.": "Vash: Du hast ein Clanduell gemeldet. Bei mir. Wie erfrischend.",
"Vash: I'll file it under 'sold'. Both clans pay well for honesty.": "Vash: Ich lege es unter 'verkauft' ab. Beide Clans zahlen gut für Ehrlichkeit.",
"Vash: Your files are safe with me. Well. Your files are with me.": "Vash: Deine Akten sind bei mir sicher. Na ja. Deine Akten sind bei mir.",
"Vash: Pleasure. The record is blank. Spotless. Like my conscience.": "Vash: Sehr erfreut. Das Protokoll ist leer. Makellos. Wie mein Gewissen.",
"Vash: The firewood for the oven is billed separately.": "Vash: Das Brennholz für den Ofen wird gesondert berechnet.",
"Vash: Pleasure. I sold a copy anyway, of course. But I left it blank.": "Vash: Sehr erfreut. Eine Abschrift hab ich natürlich trotzdem verkauft. Aber leer gelassen.",
"Vash: Professional courtesy. Don't get used to it.": "Vash: Kollegiale Höflichkeit. Gewöhn dich nicht dran.",
"The blank battle record": "Das leere Kampfprotokoll",
"Ilo Vash wrote nothing about Pip's duel, for money.": "Ilo Vash hat über Pips Duell nichts aufgeschrieben, gegen Geld.",
"Then he sold the nothing to the Ruskwebers. Twice.": "Dann hat er das Nichts an die Ruskweber verkauft. Zweimal.",
"Fenrick: Fenrick Kael, head of Haus Marrovel. You may admire the portrait later.": "Fenrick: Fenrick Kael, Oberhaupt von Haus Marrovel. Das Porträt darfst du später bewundern.",
"Fenrick: It shows my Spirling. I'm in the corner. Modesty.": "Fenrick: Es zeigt meinen Spirling. Ich bin in der Ecke. Bescheidenheit.",
"Fenrick: Take this sealed letter to the ferry post. Do not read it. Reading is for clerks.": "Fenrick: Bring diesen versiegelten Brief zur Fährpost. Nicht lesen. Lesen ist was für Schreiber.",
"Deliver it": "Zustellen",
"Read it first": "Erst lesen",
"You break the seal. Fenrick's hand: 'The one who hid the duel is the map kid.'": "Du brichst das Siegel. Fenricks Schrift: 'Wer das Duell versteckt hat, ist das Kartenkind.'",
"He meant to hand you to the Ruskwebers. Postage paid.": "Er wollte dich den Ruskwebern ausliefern. Porto bezahlt.",
"You burn the letter. Somewhere a Ruskweber waits for post that never comes.": "Du verbrennst den Brief. Irgendwo wartet ein Ruskweber auf Post, die nie kommt.",
"Fenrick: Lost in the mail? Pity. The mail is so unreliable these days.": "Fenrick: Verloren gegangen? Schade. Auf die Post ist heute kein Verlass mehr.",
"At the ferry post two Ruskweber hands are waiting. They know your face.": "An der Fährpost warten zwei Ruskweber-Handlanger. Sie kennen dein Gesicht.",
"One of them grins. 'Fenrick says hello. He also says goodbye.'": "Einer grinst. 'Fenrick lässt grüßen. Und er lässt ausrichten: Lebwohl.'",
"Fenrick: Haus Marrovel never forgets a favour. We write them down. In ink.": "Fenrick: Haus Marrovel vergisst keinen Gefallen. Wir schreiben sie auf. Mit Tinte.",
"Fenrick's sealed letter": "Fenricks versiegelter Brief",
"Fenrick named you as the one who hid Pip's duel, and posted it to the Ruskwebers.": "Fenrick hat dich als den genannt, der Pips Duell versteckt hat, und es den Ruskwebern geschickt.",
"A scapegoat is cheaper than a son.": "Ein Sündenbock ist billiger als ein Sohn.",
"Aldra: You're staring. Yes, I came through the Wide Rift. Eleven of us did.": "Aldra: Du starrst. Ja, ich kam durch den Weiten Riss. Wir waren elf.",
"Aldra: The valley calls us the strangers from the map's edge. We call that rude.": "Aldra: Das Tal nennt uns die Fremden vom Kartenrand. Wir nennen das unhöflich.",
"Aldra: The clans hire us because nobody here owes us anything. Yet.": "Aldra: Die Clans heuern uns an, weil uns hier niemand etwas schuldet. Noch nicht.",
"Aldra: Fenrick wants you to carry a letter? Read it first. Clans seal the true ones.": "Aldra: Fenrick will, dass du einen Brief trägst? Lies ihn vorher. Die Clans versiegeln die wahren.",
"Lipka: Lipka, from beyond the edge. I sell tips. True ones cost extra.": "Lipka: Lipka, von jenseits des Rands. Ich verkaufe Tipps. Wahre kosten extra.",
"Lipka: Free sample: something rare sleeps behind the old mill tonight. Believe me?": "Lipka: Gratisprobe: Hinter der alten Mühle schläft heute Nacht etwas Seltenes. Glaubst du mir?",
"I believe you": "Ich glaube dir",
"No thanks": "Nein danke",
"Lipka: Tips are like weather. Mine are like weather in the mountains.": "Lipka: Tipps sind wie Wetter. Meine sind wie Wetter im Gebirge.",
"Behind the old mill nothing rare is sleeping. Two Ruskweber hands are wide awake.": "Hinter der alten Mühle schläft nichts Seltenes. Zwei Ruskweber-Handlanger sind hellwach.",
"One of them waves a paper. 'Lipka sends her regards. And her invoice.'": "Einer wedelt mit einem Zettel. 'Lipka lässt grüßen. Und ihre Rechnung.'",
"Behind the old mill: nothing. A tip can be honest and still be wrong.": "Hinter der alten Mühle: nichts. Ein Tipp kann ehrlich sein und trotzdem falsch.",
"Behind the old mill a small crate is waiting, with your name chalked on it.": "Hinter der alten Mühle wartet eine kleine Kiste, dein Name steht mit Kreide darauf.",
"Kenan: Kenan. Edge-born, Rift runner. The clans pay me to scout the Cinder Rift.": "Kenan: Kenan. Vom Rand, Rissläufer. Die Clans zahlen mich, damit ich den Glutriss erkunde.",
"Kenan: My Spirling is hurt. Lend me your lead one for a single run? Back by dusk.": "Kenan: Mein Spirling ist verletzt. Leihst du mir deinen ersten für einen Lauf? Bis zur Dämmerung zurück.",
"Lend my lead": "Meinen leihen",
"No": "Nein",
"Kenan: Rift runs are hard on keepsakes. Ask anyone.": "Kenan: Risse sind hart zu Andenken. Frag, wen du willst.",
"Kenan comes back at dusk. Your Spirling looks fine. Lighter, somehow.": "Kenan kommt in der Dämmerung zurück. Dein Spirling sieht gut aus. Irgendwie leichter.",
"Kenan: The Rift was rough. Things fell off. Small things. Shiny things.": "Kenan: Der Riss war rau. Dinge sind abgefallen. Kleine Dinge. Glänzende Dinge.",
"Kenan brings your Spirling back at dusk, tired and proud. Nothing is missing.": "Kenan bringt deinen Spirling in der Dämmerung zurück, müde und stolz. Nichts fehlt.",
"Kenan brings your Spirling back with a little gift from the Rift edge.": "Kenan bringt deinen Spirling mit einem kleinen Geschenk vom Rissrand zurück.",
"Nail: Nail. Edge-born. I'm opening a tea stall for the Rift workers.": "Nail: Nail. Vom Rand. Ich eröffne einen Teestand für die Rissarbeiter.",
"Nail: I'm 200 coins short. I pay back with interest. Don't ask around. They'd lie.": "Nail: Mir fehlen 200 Münzen. Ich zahle mit Zinsen zurück. Frag nicht herum. Die lügen.",
"Lend 200 coins": "200 Münzen leihen",
"Nail: The tea is terrible. The Rift workers love it. Nobody understands business.": "Nail: Der Tee ist furchtbar. Die Rissarbeiter lieben ihn. Niemand versteht Geschäfte.",
"Nail: Your coins, plus interest. Don't look so shocked. Some of us are honest.": "Nail: Deine Münzen, plus Zinsen. Schau nicht so erschrocken. Manche von uns sind ehrlich.",
"Nail: Your coins back. The interest went into the tea. You can taste it.": "Nail: Deine Münzen zurück. Die Zinsen stecken im Tee. Man schmeckt es.",
"The tea stall is gone. So is Nail. A sign says 'Closed for honesty'.": "Der Teestand ist weg. Nail auch. Ein Schild sagt 'Wegen Ehrlichkeit geschlossen'.",
"Mother Grell: Mother Grell. I lead the Ruskwebers, since nobody else would.": "Mother Grell: Mother Grell. Ich führe die Ruskweber, weil es sonst keiner wollte.",
"Mother Grell: A Marrovel brat sent my best breeder into a Rift. I wear black now. It suits me.": "Mother Grell: Eine Marrovel-Göre hat meinen besten Züchter in einen Riss geschickt. Ich trage jetzt Schwarz. Steht mir.",
"Mother Grell: Carry a warning to my apprentice in the Woadfen? You have an honest face. For now.": "Mother Grell: Bringst du meinem Lehrling im Waidmoor eine Warnung? Du hast ein ehrliches Gesicht. Noch.",
"I'll carry it": "Ich bringe sie",
"Not my business": "Nicht meine Sache",
"Mother Grell: Grief is a full-time job. I hire help.": "Mother Grell: Trauer ist ein Vollzeitberuf. Ich stelle Hilfe ein.",
"Mother Grell: My apprentice left his hiding place after your warning. Marrovel blades were waiting.": "Mother Grell: Nach deiner Warnung hat mein Lehrling sein Versteck verlassen. Marrovel-Klingen haben gewartet.",
"Mother Grell: Strange how that works. I'll remember who carried it.": "Mother Grell: Seltsam, wie das läuft. Ich merke mir, wer sie getragen hat.",
"The mercy post": "Die Gnadenpost",
"You carried Mother Grell's warning to her apprentice in the Woadfen.": "Du hast Mother Grells Warnung zu ihrem Lehrling ins Waidmoor gebracht.",
"The warning sent him out of hiding. Whoever waited there knew he would come.": "Die Warnung trieb ihn aus dem Versteck. Wer dort wartete, wusste, dass er kommt.",
"Sable: Sable Ruskweber. Grell's nephew. The family's good side. I have two.": "Sable: Sable Ruskweber. Grells Neffe. Die gute Seite der Familie. Ich habe zwei.",
"Sable: Friends tell each other things. So, friend: the Woadfen road is watched.": "Sable: Freunde erzählen sich Dinge. Also, Freund: Die Straße durchs Waidmoor wird beobachtet.",
"Sable: Take the reed path instead. Trust me?": "Sable: Nimm lieber den Schilfpfad. Vertraust du mir?",
"I trust you": "Ich vertraue dir",
"Not yet": "Noch nicht",
"The reed path is quiet. Under a stone you find a pouch tied with Ruskweber thread.": "Der Schilfpfad ist ruhig. Unter einem Stein liegt ein Beutel, mit Ruskweber-Garn verschnürt.",
"Sable was right. That should worry you more than it does.": "Sable hatte recht. Das sollte dich mehr beunruhigen, als es tut.",
"The reed path is quiet. Sable was right. That should worry you.": "Der Schilfpfad ist ruhig. Sable hatte recht. Das sollte dich beunruhigen.",
"The reed path is very quiet. Then it is full of Ruskweber hands.": "Der Schilfpfad ist sehr ruhig. Dann ist er voller Ruskweber-Handlanger.",
"Farida: Farida. Edge-born. I lodged at Wren's place in Veydal all last year.": "Farida: Farida. Vom Rand. Ich habe letztes Jahr bei Wren in Veydal gewohnt.",
"Farida: Lovely woman. Never asks where her guests go at night.": "Farida: Reizende Frau. Fragt nie, wohin ihre Gäste nachts gehen.",
"Farida: I'm 400 coins short for the ferry home. Help a fellow traveller?": "Farida: Mir fehlen 400 Münzen für die Fähre nach Hause. Hilfst du einer Mitreisenden?",
"Lend 400 coins": "400 Münzen leihen",
"Farida: Home is wherever the letters get paid for.": "Farida: Zuhause ist da, wo die Briefe bezahlt werden.",
"The ferry leaves without Farida. She was never going home. Your coins went to Mother Grell's post.": "Die Fähre legt ohne Farida ab. Sie wollte nie nach Hause. Deine Münzen gingen an Mother Grells Post.",
"Farida pays you back the next morning, to the coin. She leaves no address.": "Farida zahlt dir am nächsten Morgen alles zurück, auf die Münze. Eine Adresse hinterlässt sie nicht.",
"Amir: Amir. Edge-born. I know eggs. Smuggled ones, mostly.": "Amir: Amir. Vom Rand. Ich kenne mich mit Eiern aus. Meistens mit geschmuggelten.",
"Amir: If Mother Grell sends anyone a gift, have it looked at. Eggs travel in odd places.": "Amir: Wenn Mother Grell jemandem ein Geschenk schickt, lass es untersuchen. Eier reisen an seltsamen Orten.",
"Amir: And Farida, by the crates? She writes to Mother Grell every night.": "Amir: Und Farida bei den Kisten? Sie schreibt Mother Grell jede Nacht.",
"Amir: She paid Wren on time for a whole year. That should have been the clue.": "Amir: Sie hat Wren ein ganzes Jahr pünktlich bezahlt. Das hätte uns stutzig machen sollen.",
"The spy in the guest book": "Die Spionin im Gästebuch",
"Farida lived at Wren's guest house for a year and reported every guest to Mother Grell.": "Farida wohnte ein Jahr in Wrens Pension und meldete jeden Gast an Mother Grell.",
"She always paid on time.": "Sie hat immer pünktlich gezahlt.",
"Brannoc: Brannoc Kael. Former Rift gladiator. Current disappointment.": "Brannoc: Brannoc Kael. Früher Rissgladiator. Heute Enttäuschung.",
"Brannoc: Father wants the Woadfen routes drawn up. You're the map kid. Draw them for me?": "Brannoc: Vater will die Wege durchs Waidmoor gezeichnet haben. Du bist das Kartenkind. Zeichnest du sie mir?",
"Draw the routes": "Wege zeichnen",
"Not now": "Jetzt nicht",
"Brannoc: I wanted out. Routes are a way out. Nobody said whose.": "Brannoc: Ich wollte raus. Wege führen raus. Keiner hat gesagt, wessen.",
"You draw the routes one bend wrong, as Elma said. The Ruskwebers who bought them end up in a bog.": "Du zeichnest die Wege eine Biegung falsch, wie Elma riet. Die Ruskweber, die sie kauften, landen im Sumpf.",
"Brannoc: The bog? That's... a very precise mistake.": "Brannoc: Der Sumpf? Das ist... ein sehr genauer Fehler.",
"On the Woadfen road the Ruskwebers know every bend you drew. Brannoc sold your map before the ink dried.": "Auf der Waidmoorstraße kennen die Ruskweber jede Biegung, die du gezeichnet hast. Brannoc hat deine Karte verkauft, bevor die Tinte trocken war.",
"The Woadfen routes": "Die Waidmoor-Wege",
"You drew the Woadfen routes for Brannoc Kael. He passed them to the Ruskwebers.": "Du hast Brannoc Kael die Waidmoor-Wege gezeichnet. Er gab sie an die Ruskweber weiter.",
"He wanted money of his own, and a way out of the family.": "Er wollte eigenes Geld und einen Weg aus der Familie.",
"Elma: Elma. Edge-born. I cook for the Kaels. Nobody else will, since the last feast.": "Elma: Elma. Vom Rand. Ich koche für die Kaels. Seit dem letzten Festmahl tut es sonst keiner.",
"Elma: Brannoc dined with a Ruskweber trader. The soup was excellent. Except for the guest.": "Elma: Brannoc hat mit einem Ruskweber-Händler gegessen. Die Suppe war ausgezeichnet. Bis auf den Gast.",
"Elma: Ottilie seasoned it herself. Brannoc had to watch. He hasn't been family since.": "Elma: Ottilie hat selbst gewürzt. Brannoc musste zusehen. Seitdem ist er nicht mehr Familie.",
"Elma: If Brannoc asks you for routes, draw them one bend wrong. He sells them on.": "Elma: Wenn Brannoc dich um Wege bittet, zeichne sie eine Biegung falsch. Er verkauft sie weiter.",
"The last feast": "Das letzte Festmahl",
"Brannoc bought Rift eggs behind the clan's back. Ottilie knew from the first egg.": "Brannoc kaufte Risseier am Clan vorbei. Ottilie wusste es vom ersten Ei an.",
"The trader was the main course of the lesson, if not of the meal.": "Der Händler war das Hauptgericht der Lektion, wenn auch nicht des Essens.",
"Heider: Heider. Edge-born. I sell news to both clans. Same price. I'm fair.": "Heider: Heider. Vom Rand. Ich verkaufe Neuigkeiten an beide Clans. Gleicher Preis. Ich bin fair.",
"Heider: Fresh one, free: Ottilie means to sacrifice one of her own Wardens. Believe it?": "Heider: Ganz frisch, gratis: Ottilie will einen ihrer eigenen Hüter opfern. Glaubst du das?",
"I believe it": "Ich glaube es",
"Sounds made up": "Klingt erfunden",
"Heider: News goes stale fast. People don't. They just go missing.": "Heider: Neuigkeiten werden schnell alt. Leute nicht. Die verschwinden nur.",
"The tip was true. Heider also sold the Ruskwebers the news that you believed it.": "Der Tipp stimmte. Heider hat den Ruskwebern aber auch verkauft, dass du ihn glaubst.",
"The tip was true. For once, Heider sold it to only one side.": "Der Tipp stimmte. Ausnahmsweise hat Heider ihn nur an eine Seite verkauft.",
"Morrow: Warden Captain Dace Morrow. I investigate Haus Marrovel. Thoroughly.": "Morrow: Hüterhauptmann Dace Morrow. Ich ermittle gegen Haus Marrovel. Gründlich.",
"Morrow: I also take Ottilie's coins. And Fenrick's. I keep two tills.": "Morrow: Ich nehme auch Ottilies Münzen. Und Fenricks. Ich führe zwei Kassen.",
"Ottilie: Ottilie Kael. The orphans call me Aunt. The Wardens call me Ma'am.": "Ottilie: Ottilie Kael. Die Waisen nennen mich Tante. Die Hüter nennen mich gnädige Frau.",
"Ottilie: Fenrick calls me later. I'm always there later.": "Ottilie: Fenrick nennt mich später. Ich bin immer später da.",
"Ottilie: Mother Grell sent us a show Spirling as a peace gift. Lovely plumage.": "Ottilie: Mother Grell hat uns einen Schauspirling als Friedensgabe geschickt. Herrliches Gefieder.",
"Ottilie: And Captain Morrow rides out to the Root Rift on patrol tonight. Alone. Fenrick insisted.": "Ottilie: Und Hauptmann Morrow reitet heute Nacht allein zur Wurzelriss-Patrouille. Fenrick hat darauf bestanden.",
"Ottilie: The war? I ordered it, dear. Fenrick needed a war to look small in.": "Ottilie: Der Krieg? Den habe ich bestellt, Liebes. Fenrick brauchte einen Krieg, in dem er klein aussieht.",
"Ottilie: Write that in your little book. I keep a bigger one.": "Ottilie: Schreib das in dein Büchlein. Ich führe ein größeres.",
"Amir checks the show Spirling's feathers and finds a brood capsule full of spore fever.": "Amir untersucht das Gefieder des Schauspirlings und findet eine Brutkapsel voller Sporenfieber.",
"Amir: Never look a gift Spirling in the beak? Always look. Twice.": "Amir: Einem geschenkten Spirling schaut man nicht in den Schnabel? Immer. Zweimal.",
"That night the Marrovel stables burn with fever. A sick show Spirling breaks loose, wild with it.": "In der Nacht brennen die Marrovel-Ställe vor Fieber. Ein kranker Schauspirling reißt sich los, rasend davon.",
"The gift of honour": "Das Ehrengeschenk",
"Mother Grell's peace gift carried a brood capsule of spore fever into the Marrovel stables.": "Mother Grells Friedensgabe trug eine Brutkapsel mit Sporenfieber in die Marrovel-Ställe.",
"You catch Morrow at the gate and tell him what Heider sold you. He leaves Corvane that night, with both tills.": "Du fängst Morrow am Tor ab und erzählst ihm, was Heider dir verkauft hat. Er verlässt Corvane noch in der Nacht, mit beiden Kassen.",
"Ottilie: Someone talked. How tiresome. I'll find out who. I always do.": "Ottilie: Jemand hat geredet. Wie lästig. Ich finde heraus, wer. Das tue ich immer.",
"News from the Woadfen: Captain Morrow had an accident in the Root Rift. He was a thorough man.": "Nachricht aus dem Waidmoor: Hauptmann Morrow hatte einen Unfall im Wurzelriss. Er war ein gründlicher Mann.",
"Ottilie: Fenrick's best Warden, gone. Fenrick will feel so very alone.": "Ottilie: Fenricks bester Hüter, fort. Fenrick wird sich so allein fühlen.",
"The Warden with two tills": "Der Hüter mit zwei Kassen",
"Ottilie sent Captain Morrow, Fenrick's man, alone to the Root Rift to weaken her husband.": "Ottilie schickte Hauptmann Morrow, Fenricks Mann, allein zum Wurzelriss, um ihren Gatten zu schwächen.",
"The ordered war": "Der bestellte Krieg",
"The clan war was no accident. Ottilie ordered it, to bring down her own husband.": "Der Clankrieg war kein Zufall. Ottilie hat ihn bestellt, um ihren eigenen Gatten zu stürzen.",
"Someone sent Pip to that duel. The ink was hers.": "Jemand hat Pip zu diesem Duell geschickt. Die Tinte war ihre.",
"Vash: Chief Warden Vash now. Both clans backed me. Each thinks I'm theirs.": "Vash: Jetzt Oberster Hüter Vash. Beide Clans haben mich gestützt. Jeder hält mich für seinen.",
"Vash: New rule: Rift duels need a permit. Permits cost money. I love rules.": "Vash: Neue Regel: Rissduelle brauchen eine Genehmigung. Genehmigungen kosten Geld. Ich liebe Regeln.",
"Sable: Old friend! There's a card hall under the basalt. Come play. Friends only.": "Sable: Alter Freund! Unter dem Basalt gibt es einen Kartensaal. Komm spielen. Nur für Freunde.",
"Sable: Bring your strongest Spirling. Card halls get rowdy.": "Sable: Bring deinen stärksten Spirling mit. In Kartensälen wird es laut.",
"I'll come": "Ich komme",
"Later": "Später",
"Sable: Nothing personal. It was a business decision. You were the business.": "Sable: Nichts Persönliches. Eine Geschäftsentscheidung. Du warst das Geschäft.",
"Under the basalt there are no cards. Only Marrovel's enemies, and a price on your head.": "Unter dem Basalt gibt es keine Karten. Nur Marrovels Feinde und ein Preis auf deinen Kopf.",
"Sable: I said friends only. They're my friends.": "Sable: Ich sagte, nur für Freunde. Das sind meine Freunde.",
"You come in through the coal chute, behind the ambush. The hands turn to Sable.": "Du kommst durch die Kohlenrutsche, hinter dem Hinterhalt. Die Handlanger sehen Sable an.",
"Sable: Ah. You read the room. I hate it when people read.": "Sable: Ah. Du hast den Raum gelesen. Ich hasse es, wenn Leute lesen.",
"The card hall": "Der Kartensaal",
"Sable Ruskweber invited you to a card hall as a friend and sold you to the highest bidder.": "Sable Ruskweber lud dich als Freund in einen Kartensaal und verkaufte dich an den Meistbietenden.",
"Mirza: Mirza. Edge-born. I play cards with Sable. I lose on purpose. It pays.": "Mirza: Mirza. Vom Rand. Ich spiele Karten mit Sable. Ich verliere absichtlich. Das zahlt sich aus.",
"Mirza: Stake me 300 coins tonight? I win, you win.": "Mirza: Setzt du heute Nacht 300 Münzen auf mich? Ich gewinne, du gewinnst.",
"Stake 300 coins": "300 Münzen setzen",
"Mirza: Cards are honest. It's the players you have to watch.": "Mirza: Karten sind ehrlich. Auf die Spieler musst du achten.",
"Mirza: We won. Your share, plus mine, minus nothing. Don't tell anyone I'm generous.": "Mirza: Wir haben gewonnen. Dein Anteil, plus meiner, minus nichts. Erzähl keinem, dass ich großzügig bin.",
"Mirza: And if Sable invites you to his card hall: there are no cards. Use the coal chute.": "Mirza: Und wenn Sable dich in seinen Kartensaal einlädt: Da gibt es keine Karten. Nimm die Kohlenrutsche.",
"Mirza: We broke even. Your stake, back. Now a free tip.": "Mirza: Plus minus null. Dein Einsatz zurück. Jetzt ein Gratistipp.",
"Mirza: If Sable invites you to his card hall: there are no cards. Use the coal chute.": "Mirza: Wenn Sable dich in seinen Kartensaal einlädt: Da gibt es keine Karten. Nimm die Kohlenrutsche.",
"Mirza lost your stake. On purpose, he says. It paid. Just not you.": "Mirza hat deinen Einsatz verloren. Absichtlich, sagt er. Es hat sich gelohnt. Nur nicht für dich.",
"Leith: Leith. Edge-born. I run errands for Sable.": "Leith: Leith. Vom Rand. Ich mache Botengänge für Sable.",
"Leith: Tip for free: the basalt shortcut to the Kiln Rift is safe now. Believe me?": "Leith: Gratistipp: Die Basaltabkürzung zum Ofenriss ist jetzt sicher. Glaubst du mir?",
"Who sent you?": "Wer schickt dich?",
"Leith: ...Sable did. He's selling you at his card hall. I never said that.": "Leith: ...Sable. Er verkauft dich in seinem Kartensaal. Das hab ich nie gesagt.",
"Leith: Nobody sent me. I just like you. Everybody likes you.": "Leith: Niemand schickt mich. Ich mag dich einfach. Alle mögen dich.",
"Leith: Errands, errands. Somebody has to carry the bad news.": "Leith: Botengänge, Botengänge. Irgendwer muss die schlechten Nachrichten tragen.",
"The basalt shortcut is not safe. It is full of people Sable owes favours.": "Die Basaltabkürzung ist nicht sicher. Sie ist voller Leute, denen Sable Gefallen schuldet.",
"The basalt shortcut really is safe. Leith looks almost as surprised as you.": "Die Basaltabkürzung ist wirklich sicher. Leith wirkt fast so überrascht wie du.",
"Marlo: Ashmere air is terrible for wings. Business is booming.": "Marlo: Die Luft in Ashmere ist furchtbar für Flügel. Das Geschäft blüht.",
"Marlo: Clan people asked me where you were the night of Pip's duel.": "Marlo: Clanleute haben mich gefragt, wo du in der Nacht von Pips Duell warst.",
"Marlo: I said: with me. They didn't like that answer. I may need to lie low.": "Marlo: Ich sagte: bei mir. Die Antwort gefiel ihnen nicht. Ich sollte vielleicht untertauchen.",
"That night masked hands come for Marlo. He is busy setting a Shalebat's wing.": "In der Nacht kommen Maskierte für Marlo. Er schient gerade einem Shalebat den Flügel.",
"Marlo: Rude of them to wait. I made them hold the bandage. They left with clean hands.": "Marlo: Unhöflich, so zu warten. Ich ließ sie den Verband halten. Sie gingen mit sauberen Händen.",
"In the morning Marlo's clinic stands open. His bag sits by the spring, still packed.": "Am Morgen steht Marlos Praxis offen. Seine Tasche steht an der Quelle, noch gepackt.",
"Someone paid for the lies he told for you. The Ledger doesn't say who.": "Jemand hat für die Lügen bezahlt, die er für dich erzählt hat. Das Schuldbuch sagt nicht, wer.",
"The alibi": "Das Alibi",
"Marlo swore you were with him the night of Pip's duel. Every time you asked.": "Marlo schwor, du warst in der Nacht von Pips Duell bei ihm. Jedes Mal, wenn du gefragt hast.",
"An alibi is a debt that the alibi pays.": "Ein Alibi ist eine Schuld, die das Alibi bezahlt.",
"Lejla: Lejla. Edge-born. I copy documents. Sometimes the copies are better.": "Lejla: Lejla. Vom Rand. Ich kopiere Dokumente. Manchmal sind die Kopien besser.",
"Lejla: Pip asked me to read the old Kael breeding registers. Look at the bond seals.": "Lejla: Pip bat mich, die alten Brutregister der Kaels zu lesen. Sieh dir die Bindungssiegel an.",
"Lejla: Pip's seal matches Fenrick's line. Not Brannoc's. Fenrick is her father.": "Lejla: Pips Siegel passt zu Fenricks Linie. Nicht zu Brannocs. Fenrick ist ihr Vater.",
"Lejla: And Leith? He talks to people he trusts. I told him you're dull. He trusts dull.": "Lejla: Und Leith? Er redet mit Leuten, denen er traut. Ich sagte ihm, du bist langweilig. Langweiligen traut er.",
"The seal in the breeding register": "Das Siegel im Brutregister",
"Pip's bond seal matches Fenrick's line, not Brannoc's. Fenrick is her father.": "Pips Bindungssiegel passt zu Fenricks Linie, nicht zu Brannocs. Fenrick ist ihr Vater.",
"Pip: Lejla is reading the old registers for me. Don't tell anyone. Especially family.": "Pip: Lejla liest die alten Register für mich. Sag es niemandem. Vor allem nicht der Familie.",
"Pip: I thought I had his eyes. They were someone else's.": "Pip: Ich dachte, ich hätte seine Augen. Es waren die eines anderen.",
"Pip: And the note that sent me to that duel? Same ink as Grandmother's letters.": "Pip: Und der Zettel, der mich zum Duell schickte? Dieselbe Tinte wie Großmutters Briefe.",
"Brannoc: Ashmere. Nobody here knows my name. I could get used to that.": "Brannoc: Ashmere. Hier kennt keiner meinen Namen. Daran könnte ich mich gewöhnen.",
"Brannoc: So Pip is Father's. And I was the cover story. I'm done with Marrovel.": "Brannoc: Pip ist also von Vater. Und ich war die Ausrede. Ich bin fertig mit Marrovel.",
"Mother Grell: You again. Alive. Sable must be losing his touch.": "Mother Grell: Du schon wieder. Lebendig. Sable lässt nach.",
"Mother Grell: My breeder? He's fine. Under the station, counting eggs.": "Mother Grell: Mein Züchter? Dem geht es gut. Unter dem Bahnhof, beim Eierzählen.",
"Mother Grell: Grief was cheaper than a war. And it paid much better.": "Mother Grell: Trauer war billiger als ein Krieg. Und sie hat viel besser bezahlt.",
"The breeder who lived": "Der Züchter, der lebte",
"Mother Grell's breeder never died in the Rift. She hid him and staged her grief.": "Mother Grells Züchter starb nie im Riss. Sie hat ihn versteckt und ihre Trauer inszeniert.",
"Fenrick: My bond seal is fading. Some nights my Spirling forgets whose side it is on.": "Fenrick: Mein Bindungssiegel verblasst. Manche Nächte vergisst mein Spirling, auf wessen Seite er steht.",
"Fenrick: Some nights so do I. Ottilie says it's my age. Ottilie says many things.": "Fenrick: Manche Nächte ich auch. Ottilie sagt, es ist das Alter. Ottilie sagt vieles.",
"The hands take what they came for and leave you by the road. Nothing personal.": "Die Handlanger nehmen, weswegen sie kamen, und lassen dich am Weg liegen. Nichts Persönliches.",
"You don't have that many coins.": "So viele Münzen hast du nicht.",
"A new entry in your Ledger.": "Ein neuer Eintrag in deinem Schuldbuch.",
"%s came back without its keepsake (%s).": "%s kam ohne sein Andenken zurück (%s).",
"Ledger": "Schuldbuch",
"Ledger (%d)": "Schuldbuch (%d)",
"Ruskweber Hand": "Ruskweber-Handlanger",
"Fevered Show Spirling": "Fiebriger Schauspirling",
}
